275: // VerifyTask runs the task verification command inside the isolated workspace.
276: func VerifyTask(record *RunRecord, task Task, timeout time.Duration) error {
277: 	if task.VerifyCommand == "" || record.WorkDir == "" {
278: 		return nil
279: 	}
280: 	if timeout <= 0 {
281: 		timeout = 2 * time.Minute
282: 	}
283: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
284: 	defer cancel()
285: 	parts := strings.Fields(task.VerifyCommand)
286: 	if len(parts) == 0 {
287: 		return nil
288: 	}
289: 	cmd := exec.CommandContext(ctx, parts[0], parts[1:]...)
290: 	cmd.Dir = record.WorkDir
291: 	output, err := cmd.CombinedOutput()
292: 	record.VerifyOutput = string(output)
293: 	if exitError, ok := err.(*exec.ExitError); ok {
294: 		record.VerifyExitCode = exitError.ExitCode()
295: 	} else if err != nil {
296: 		record.VerifyExitCode = -1
297: 	}
298: 	record.VerifyPassed = err == nil
299: 	return nil
300: }
