381: 		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
382: 			return "", err
383: 		}
384: 		if err := os.WriteFile(path, []byte(task.Files[name]), 0o644); err != nil {
385: 			return "", err
386: 		}
387: 	}
388: 	return dir, nil
389: }
